css:
.hqr-sheet { display: flex; flex-wrap: wrap; gap: 4mm; align-content: flex-start; }
.hqr-bcard {
    position: relative;
    width: 85.6mm; height: 53.98mm;
    border-radius: 3.5mm; overflow: hidden;
    background: #fdf6ee; color: #4e342e;
    border: 0.4mm solid #d7a96b;
    font-family: "Helvetica Neue", Arial, sans-serif;
    display: flex; flex-direction: column; align-items: center; justify-content: center;
    box-sizing: border-box; padding: 4mm;
    page-break-inside: avoid; break-inside: avoid;
}
.hqr-baccent {
    position: absolute; top: 0; left: 0; right: 0; height: 2mm;
    background: linear-gradient(90deg, #d7a96b 0%, #f0c98a 50%, #d7a96b 100%);
}
.hqr-bbrand { font-size: 6.5pt; letter-spacing: 0.8pt; text-transform: uppercase; color: #a5754a; font-weight: 700; margin-bottom: 1.5mm; }
.hqr-bqr { width: 28mm; height: 28mm; background: #fff; padding: 1.6mm; border-radius: 2mm; box-sizing: border-box; border: 0.2mm solid #e4d3bd; }
.hqr-bid { margin-top: 2mm; font-size: 12pt; font-weight: 800; letter-spacing: 0.5pt; color: #4e342e; }
.hqr-bsub { font-size: 6pt; letter-spacing: 1.2pt; text-transform: uppercase; color: #b89066; margin-top: 0.6mm; }
